source='''def transform(grid):
    """Extend each solid 3x3 colored square along its center row and column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find the centers of monochrome, nonzero 3x3 objects.
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
    # Rays are lines across the entire canvas. Conflicting ray crossings stay blank;
    # original nonzero input cells are never overwritten.
    marks = {}
    for r, c, color in objects:
        for cc in range(w):
            marks.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            marks.setdefault((rr, c), set()).add(color)
    for (r, c), colors in marks.items():
        if grid[r][c] != 0:
            continue
        if len(colors) == 1:
            out[r][c] = next(iter(colors))
    return out
